export interface AnnouncementBarProps {
  message: string;
  mapLinks?: {
    url: string;
  }[];
  backgroundColor?: string;
  textColor?: string;
  className?: string;
}

/**
 * Usage:
 *
 *  <announcement-bar></announcement-bar>
 *
 */
class AnnouncementBar extends HTMLElement {
  get _root() {
    return this.shadowRoot || this;
  }

  constructor() {
    super();
    const self = this;

    this.state = {};
    if (!this.props) {
      this.props = {};
    }

    this.componentProps = [
      "className",
      "backgroundColor",
      "textColor",
      "mapLinks",
      "message",
    ];

    // used to keep track of all nodes created by show/for
    this.nodesToDestroy = [];
    // batch updates
    this.pendingUpdate = false;

    if (undefined) {
      this.attachShadow({ mode: "open" });
    }
  }

  destroyAnyNodes() {
    // destroy current view template refs before rendering again
    this.nodesToDestroy.forEach((el) => el.remove());
    this.nodesToDestroy = [];
  }

  connectedCallback() {
    this.getAttributeNames().forEach((attr) => {
      const jsVar = attr.replace(/-/g, "");
      const regexp = new RegExp(jsVar, "i");
      this.componentProps.forEach((prop) => {
        if (regexp.test(prop)) {
          let attrValue: any = this.getAttribute(attr);
          try {
            if (attrValue && (attrValue.trim().startsWith('{') || attrValue.trim().startsWith('['))) {
              attrValue = JSON.parse(attrValue);
            }
          } catch (e) {}
          if (this.props[prop] !== attrValue) {
            this.props[prop] = attrValue;
          }
        }
      });
    });

    this._root.innerHTML = `
      <div data-el="div-announcement-bar-1">
        <template data-el="show-announcement-bar">
          <a class="cv-announcement-link" data-el="a-announcement-bar-1">
            <template data-el="div-announcement-bar-2">
              <!-- props.message -->
            </template>
          </a>
        </template>
        <template data-el="show-announcement-bar-2">
          <span class="cv-announcement-text">
            <template data-el="div-announcement-bar-3">
              <!-- props.message -->
            </template>
          </span>
        </template>
      </div>`;
    this.pendingUpdate = true;

    this.render();
    this.onMount();
    this.pendingUpdate = false;
    this.update();
  }

  showContent(el) {
    // https://developer.mozilla.org/en-US/docs/Web/API/HTMLTemplateElement/content
    // grabs the content of a node that is between <template> tags
    // iterates through child nodes to register all content including text elements
    // attaches the content after the template

    const elementFragment = el.content.cloneNode(true);
    const children = Array.from(elementFragment.childNodes);
    children.forEach((child) => {
      if (el?.scope) {
        child.scope = el.scope;
      }
      if (el?.context) {
        child.context = el.context;
      }
      this.nodesToDestroy.push(child);
    });
    el.after(elementFragment);
  }

  onMount() {}

  onUpdate() {}

  update() {
    if (this.pendingUpdate === true) {
      return;
    }
    this.pendingUpdate = true;
    this.render();
    this.onUpdate();
    this.pendingUpdate = false;
  }

  render() {
    // re-rendering needs to ensure that all nodes generated by for/show are refreshed
    this.destroyAnyNodes();
    this.updateBindings();
  }

  updateBindings() {
    this._root
      .querySelectorAll("[data-el='div-announcement-bar-1']")
      .forEach((el) => {
        el.className = `cv-announcement-bar ${this.props.className || ""}`;
        Object.assign(el.style, {
          // Defaults pair white text with violet-700, which measures 7.10:1 --
          // clearing WCAG 2.1 AAA. The previous violet-500 (#8b5cf6) default was
          // only 4.23:1, failing even AA. Falls back through the shared primary
          // token so a consumer theming the library gets their colour, not this
          // hardcoded one.
          backgroundColor:
            this.props.backgroundColor || "var(--cv-color-primary, #6d28d9)",
          color: this.props.textColor || "#ffffff",
        });
      });

    this._root
      .querySelectorAll("[data-el='show-announcement-bar']")
      .forEach((el) => {
        const whenCondition =
          this.props.mapLinks && this.props.mapLinks.length > 0;
        if (whenCondition) {
          this.showContent(el);
        }
      });

    this._root
      .querySelectorAll("[data-el='a-announcement-bar-1']")
      .forEach((el) => {
        el.setAttribute("href", this.props.mapLinks?.[0]?.url);
      });

    this._root
      .querySelectorAll("[data-el='div-announcement-bar-2']")
      .forEach((el) => {
        this.renderTextNode(el, this.props.message);
      });

    this._root
      .querySelectorAll("[data-el='show-announcement-bar-2']")
      .forEach((el) => {
        const whenCondition = !(
          this.props.mapLinks && this.props.mapLinks.length > 0
        );
        if (whenCondition) {
          this.showContent(el);
        }
      });

    this._root
      .querySelectorAll("[data-el='div-announcement-bar-3']")
      .forEach((el) => {
        this.renderTextNode(el, this.props.message);
      });
  }

  // Helper to render content
  renderTextNode(el, text) {
    const textNode = document.createTextNode(text);
    if (el?.scope) {
      textNode.scope = el.scope;
    }
    if (el?.context) {
      textNode.context = el.context;
    }
    el.after(textNode);
    this.nodesToDestroy.push(el.nextSibling);
  }
}

customElements.define("announcement-bar", AnnouncementBar);
